// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(address caller, uint64 n, uint64 ts, uint256 bf, bytes32 h, uint64 seq, bytes32 bh, uint256 oh, uint256 sc) public {
        bool ok;
        vm.prank(caller);
        try c.setL1BlockValues(n, ts, bf, h, seq, bh, oh, sc) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == (caller == address(0)), "setL1BlockValues must succeed exactly for the depositor-check target");
    }
}
